impl CapabilityClient for FeatureFlagAdminClient {
    type Dependencies = PluginDependencies;
    type Error = RuntimeFailure;

    const CAPABILITY_ID: &'static str = CAPABILITY_ID;
    const DESCRIPTOR_VERSION: &'static str = DESCRIPTOR_VERSION;

    fn from_dependencies(dependencies: &PluginDependencies) -> Result<Self, RuntimeFailure> {
        Ok(Self {
            archive_flag: dependencies.one::<FeatureFlagAdminArchiveFlag>()?,
            create_flag: dependencies.one::<FeatureFlagAdminCreateFlag>()?,
            get_flag: dependencies.one::<FeatureFlagAdminGetFlag>()?,
            list_evaluation_receipts: dependencies.one::<FeatureFlagAdminListEvaluationReceipts>()?,
            list_flags: dependencies.one::<FeatureFlagAdminListFlags>()?,
            publish_ruleset: dependencies.one::<FeatureFlagAdminPublishRuleset>()?,
            put_environment: dependencies.one::<FeatureFlagAdminPutEnvironment>()?,
            update_flag: dependencies.one::<FeatureFlagAdminUpdateFlag>()?,
        })
    }

    fn already_connected() -> RuntimeFailure {
        RuntimeFailure::PluginFailure {
            detail: format!("Capability Port {CAPABILITY_ID} was connected more than once"),
        }
    }
}

impl CapabilityClientMany for FeatureFlagAdminClient {
    fn many_from_dependencies(
        dependencies: &PluginDependencies,
    ) -> Result<Vec<BoundCapabilityClient<Self>>, RuntimeFailure> {
        dependencies
            .bindings()
            .iter()
            .filter(|binding| binding.capability_id() == CAPABILITY_ID)
            .map(|binding| {
                Ok(BoundCapabilityClient::new(
                    binding.provider_instance(),
                    Self {
                    archive_flag: binding.handle().ok_or(RuntimeFailure::Unavailable { capability: CAPABILITY_ID })?.typed::<FeatureFlagAdminArchiveFlag>()?,
                    create_flag: binding.handle().ok_or(RuntimeFailure::Unavailable { capability: CAPABILITY_ID })?.typed::<FeatureFlagAdminCreateFlag>()?,
                    get_flag: binding.handle().ok_or(RuntimeFailure::Unavailable { capability: CAPABILITY_ID })?.typed::<FeatureFlagAdminGetFlag>()?,
                    list_evaluation_receipts: binding.handle().ok_or(RuntimeFailure::Unavailable { capability: CAPABILITY_ID })?.typed::<FeatureFlagAdminListEvaluationReceipts>()?,
                    list_flags: binding.handle().ok_or(RuntimeFailure::Unavailable { capability: CAPABILITY_ID })?.typed::<FeatureFlagAdminListFlags>()?,
                    publish_ruleset: binding.handle().ok_or(RuntimeFailure::Unavailable { capability: CAPABILITY_ID })?.typed::<FeatureFlagAdminPublishRuleset>()?,
                    put_environment: binding.handle().ok_or(RuntimeFailure::Unavailable { capability: CAPABILITY_ID })?.typed::<FeatureFlagAdminPutEnvironment>()?,
                    update_flag: binding.handle().ok_or(RuntimeFailure::Unavailable { capability: CAPABILITY_ID })?.typed::<FeatureFlagAdminUpdateFlag>()?,
                    },
                ))
            })
            .collect()
    }
}

